#include <bits/stdc++.h>
int main(int c, char** v) { std::mt19937 r(atoi(v[1])); int n = r() % 7 + 2; std::set<std::pair<int,int>> s; std::vector<std::array<int,3>> e; for (int i = 2; i <= n; i++) { int a = r() % (i - 1) + 1; s.insert({a, i}); e.push_back({a, i, int(r() % 20 + 1)}); } int extra = r() % 6; while (extra--) { int a = r() % n + 1, b = r() % n + 1; if (a > b) std::swap(a, b); if (a != b && !s.count({a, b})) { s.insert({a, b}); e.push_back({a, b, int(r() % 20 + 1)}); } } int k = r() % std::min(400, n * (n - 1) / 2) + 1; printf("%d %d %d\n", n, (int)e.size(), k); for (auto [a, b, w] : e) printf("%d %d %d\n", a, b, w); }
